    c.search = String(c.search ?? '').trim();
    c.spreadsheetId = String(c.spreadsheetId ?? '').trim();
    c.resumeRunId = String(c.resumeRunId ?? '').trim();
    if (c.search.length < 2 || c.search.length > 100 || /[\r\n]/.test(c.search)) throw new Error('Enter one search phrase (2–100 characters).');
    if (!/^[A-Za-z0-9_-]{20,100}$/.test(c.spreadsheetId)) throw new Error('Paste the spreadsheet ID, not its URL, before starting a paid run.');
    if (c.resumeRunId && !/^[A-Za-z0-9]{17}$/.test(c.resumeRunId)) throw new Error('resumeRunId must be a 17-character Apify run ID.');
